interactions.sample_code:
function relax(u, v, w) {
  const candidate = dist[u] + w;
  if (less(candidate, dist[v])) {
    setDist(v, candidate);
    setPred(v, u);
    markEdge(u, v, "improved");
  } else {
    markEdge(u, v, "unchanged");
  }
}

